1	import { Box, Button, CloseButton, Dialog, Flex, Icon, Stack, Text } from "@chakra-ui/react";
2	import { MarkdownEditor } from "@pstdio/ui/rich-text";
3	import { ChevronRight, Circle, Paperclip } from "lucide-react";
4	import { useRef, useState } from "react";
5	import { useTranslation } from "react-i18next";
6	import { useProjectSettingsStore } from "@/features/project-settings/store";
7	import { SingleTagSelector } from "@/features/ticket/components/single-tag-selector";
8	import type { TicketStatus, TicketStatusOption, TicketTag } from "@/features/ticket-list/types";
9	
10	interface CreateTicketModalProps {
11	  open: boolean;
12	  onClose: () => void;
13	  onSubmit: (payload: CreateTicketModalPayload) => void | Promise<void>;
14	  isSubmitting?: boolean;
15	  targetStatus?: TicketStatus | null;
16	  tags?: TicketTag[];
17	  parentId?: string | null;
18	  title?: string;
19	  submitLabel?: string;
20	  projectName?: string;
21	  statusOptions?: TicketStatusOption[];
22	}
23	
24	export interface CreateTicketModalPayload {
25	  content: string;
26	  tagIds: string[];
27	  status: TicketStatus | null;
28	  parentId: string | null;
29	  files: File[];
30	}
31	
32	export type { CreateTicketModalProps };
33	
34	const STATUS_COLOR_MAP: Record<string, string> = {
35	  gray: "gray.400",
36	  red: "red.400",
37	  orange: "orange.400",
38	  yellow: "yellow.400",
39	  green: "green.400",
40	  teal: "teal.400",
41	  blue: "blue.400",
42	  cyan: "cyan.400",
43	  purple: "purple.400",
44	  pink: "pink.400",
45	};
46	
47	export const CreateTicketModal = (props: CreateTicketModalProps) => {
48	  const {
49	    open,
50	    onClose,
51	    onSubmit,
52	    isSubmitting = false,
53	    targetStatus = null,
54	    tags = [],
55	    parentId = null,
56	    title: modalTitle,
57	    submitLabel: submitButtonLabel,
58	    projectName,
59	    statusOptions = [],
60	  } = props;
61	  const { t } = useTranslation("tickets");
