27	import { getVisibleTickets } from "../utils/ticket-visibility";
28	
29	export const TicketsPanel = () => {
30	  const { projectId } = useParams({ strict: false });
31	  const { data: project, isLoading: isProjectLoading } = useProject(projectId);
32	  const { data: tickets, sessionsByWorkspace, isLoading: isTicketsLoading } = useProjectTickets(projectId);
33	  const updateTicketStatus = useUpdateProjectTicketStatus(projectId);
34	  const updateTicket = useUpdateProjectTicket(projectId);
35	  const createTicket = useCreateProjectTicket(projectId);
36	  const navigate = useNavigate();
37	
38	  const setSessionModalState = useProjectSettingsStore((s) => s.setSessionModalState);
39	  const setSelectedSessionId = useProjectSettingsStore((s) => s.setSelectedSessionId);
40	  const { t } = useTranslation("tickets");
41	  const [settings] = useState<DisplaySettings>(DEFAULT_DISPLAY_SETTINGS);
42	  const [createModalOpen, setCreateModalOpen] = useState(false);
43	  const [createModalStatus, setCreateModalStatus] = useState<TicketStatus | null>(null);
44	
45	  const isLoading = isProjectLoading || isTicketsLoading;
46	  const statusOptions = project?.ticketStatusOptions ?? [];
47	  const allTickets = getVisibleTickets(tickets ?? []);
48	  const latestAttemptsByTicketId = buildLatestAttemptsByTicketId(allTickets);
49	  const attemptDiffInputs = [...latestAttemptsByTicketId.values()].map((attempt) => ({
50	    workspaceId: attempt.id,
51	    settled: isSessionSettled(attempt.sessionStatus),
52	  }));
53	  const { diffTotalsByWorkspaceId } = useTicketAttemptDiffs(attemptDiffInputs);
54	
55	  const groups = groupTickets(allTickets, settings.grouping, statusOptions).map((group) => ({
56	    ...group,
57	    tickets: orderTickets(group.tickets, settings.ordering),
58	  }));
59	
60	  const tagDefs = project?.ticketTags ?? [];
61	  const tagEntries = tagDefs.flatMap((t) =>
62	    t.options.map((o) => ({ id: o.id, name: o.name, color: o.color, tagName: t.name })),
63	  );
64	  const badgeContext: BadgeContext = {
65	    statusOptions: statusOptions.map((s) => ({ name: s.name, color: s.color })),
66	    tags: tagEntries,
67	    tagMap: new Map(tagEntries.map((e) => [e.id, e])),
68	    ticketShorthandById: Object.fromEntries(allTickets.map((ticket) => [ticket.id, ticket.shorthand])),
69	  };
70	
71	  const firstCreatableStatus = statusOptions.find((s) => s.canCreate)?.name ?? null;
72	
73	  const openCreateModal = (status?: TicketStatus) => {
74	    setCreateModalStatus(status ?? firstCreatableStatus);
75	    setCreateModalOpen(true);
76	  };
77	
78	  const closeCreateModal = () => {
79	    setCreateModalOpen(false);
80	    setCreateModalStatus(null);
81	  };
82	
83	  const handleOpenSessionBubble = (sessionId: string | null) => {
84	    return openTicketSessionBubble({
85	      sessionId,
86	      setSessionModalState,
87	      setSelectedSessionId,
88	      forceBubble: true,
89	    });
90	  };
91	
92	  const handleMoveTicket = (ticketId: string, status: TicketStatus) => {
93	    const targetStatus = statusOptions.find((col) => col.id === status || col.name === status);
94	    const resolvedStatus = targetStatus?.name ?? status;
95	
96	    updateTicketStatus.mutateAsync({ ticketId, status: resolvedStatus }).catch((error) => {
97	      console.error("[move ticket]", error);
98	    });
99	  };
100	
101	  const handleCreateTicket = async (payload: CreateTicketModalPayload) => {
102	    if (createTicket.isPending) return;
103	
104	    try {
105	      const createdTicket = await createTicket.mutateAsync({
106	        title: payload.content,
107	        content: payload.content,
108	        tagIds: payload.tagIds,
109	        status: payload.status,
110	        parentId: payload.parentId,
111	      });
112	
113	      closeCreateModal();
114	
115	      if (payload.files.length > 0) {
116	        try {
117	          await Promise.all(payload.files.map((file) => uploadTicketFile(createdTicket.id, file)));
118	        } catch (error) {
119	          console.error("[create ticket file upload]", error);
120	        }
121	      }
122	    } catch (error) {
123	      console.error("[create ticket]", error);
124	      throw error;
125	    }
126	  };
127	
128	  const handleColumnAction = async (status: TicketStatus, action: TicketColumnAction) => {
129	    if (action !== "archive_all") return;
130	
131	    const sourceStatus = statusOptions.find((col) => col.id === status || col.name === status);
132	
133	    if (!sourceStatus) {
134	      console.error("[archive all] Ticket status not found.");
135	      return;
136	    }
137	
138	    const ticketsInColumn = allTickets
139	      .filter((t) => t.status === sourceStatus.name)
140	      .sort((a, b) => a.shorthand.localeCompare(b.shorthand) || a.id.localeCompare(b.id));
141	
142	    const results = await Promise.allSettled(
143	      ticketsInColumn.map((t) => updateTicket.mutateAsync({ ticketId: t.id, archived: true })),
144	    );
145	
146	    const firstFailure = results.find((r) => r.status === "rejected");
147	
148	    if (firstFailure && firstFailure.status === "rejected") {
149	      console.error("[archive all]", firstFailure.reason);
150	    }
151	  };
152	
153	  const navigateToTicket = (shorthand: string) => {
